/*
 * Shared element inventory for the /reference section: the generated
 * index plus the hand-authored supplement, one flat sorted list, and the
 * slug/href helpers every consumer (index, element pages, sitemap) shares
 * so the paths cannot drift.
 *
 * data/elements.json is generated by scripts/build-elements-index.mjs in
 * noizu-labs-ml/npl-enhanced-content from spec/schema/*.md — never
 * hand-edit it. data/reference-glossary.ts supplements the eight elements
 * the generator cannot emit (see its header).
 */

import elementsIndex from "@/data/elements.json";
import {
  GLOSSARY_TAGS,
  type TagRecord,
} from "@/data/reference-glossary";

type ElementsIndex = {
  $comment: string;
  specVersion: string;
  generatedFrom: string[];
  tagCount: number;
  tags: TagRecord[];
  gaps: Array<{ tag: string; missing: string[] }>;
};

const INDEX = elementsIndex as ElementsIndex;

/** Spec version the generated half of the inventory was built from. */
export const SPEC_VERSION = INDEX.specVersion;

/** Every element, generated and hand-authored, sorted by name. */
export const ALL_TAGS: TagRecord[] = [...INDEX.tags, ...GLOSSARY_TAGS].sort(
  (a, b) => a.name.localeCompare(b.name),
);

export const SEM_TAGS = ALL_TAGS.filter((t) => t.family === "sem");
export const NPL_TAGS = ALL_TAGS.filter((t) => t.family === "npl");

/** Schema fields the generator could not find, per tag (usually empty). */
export const GAP_MISSING = new Map(INDEX.gaps.map((g) => [g.tag, g.missing]));

/*
 * URL slug for an element page: /reference/<slug>/. Every generated and
 * hand-authored tag name is already lowercase ASCII with hyphens (they are
 * XML names, lowercase by convention), so the slug IS the name; the
 * normalisation below is a guard — if a future name ever needed rewriting
 * the mismatch throws at build time rather than shipping a broken link.
 */
export function tagSlug(name: string): string {
  const slug = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  if (slug !== name) {
    throw new Error(`tag name is not URL-safe as-is: ${name} -> ${slug}`);
  }
  return slug;
}

/** Canonical href of an element's own page. */
export function tagHref(name: string): string {
  return `/reference/${tagSlug(name)}/`;
}

/** The element a slug belongs to, or undefined. */
export function tagBySlug(slug: string): TagRecord | undefined {
  return ALL_TAGS.find((t) => tagSlug(t.name) === slug);
}
